//! The rider name online races show over the rider (dhd.ini `name`, DHD_NET_NAME): the one rule for
//! the launcher's rider card (through its settings_schema and save_setting commands) and the game's
//! online menu (port/hle/online_menu.c, inside the game core, which has no Rust: it reads
//! SETTING_NAME_* from port/hle/settings_table.h, generated by `table::c_table`).

/// The characters a name may hold.
pub const LETTERS: &str = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 -";
/// Its longest length.
pub const MAX: usize = 12;
/// The rule in words, for the menus' hints.
pub const RULE: &str = "Up to 12 letters, digits, spaces or dashes.";
/// The name the game rides under while none is set.
pub const UNNAMED: &str = "RIDER";

/// `text` as a name can hold it: upper case (ASCII), only LETTERS, at most MAX of them. What a field
/// keeps while the player types.
pub fn clean(text: &str) -> String {
    text.chars().map(|c| c.to_ascii_uppercase()).filter(|&c| LETTERS.contains(c)).take(MAX).collect()
}

/// The name saved for `text`: `clean`, without spaces at either end ("": no name).
pub fn normalise(text: &str) -> String {
    clean(text).trim_matches(' ').to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_rule() {
        assert_eq!(clean("sk-uza 99!é"), "SK-UZA 99");
        assert_eq!(clean("abcdefghijklmnop"), "ABCDEFGHIJKL");
        assert_eq!(normalise("  bo b  "), "BO B");
        assert_eq!(normalise("!!"), "");
        assert!(RULE.contains(&MAX.to_string()));
    }
}
